var compressImageFile = (file, maxWidth = 1200, maxHeight = 1200, quality = .7) => {
	return new Promise((resolve) => {
		if (!file.type.startsWith("image/")) {
			resolve(file);
			return;
		}
		const timeoutId = setTimeout(() => {
			console.warn("Image compression timed out. Falling back to original file.");
			resolve(file);
		}, 4e3);
		try {
			const reader = new FileReader();
			reader.onload = (event) => {
				try {
					const img = new Image();
					img.onload = () => {
						try {
							clearTimeout(timeoutId);
							const canvas = document.createElement("canvas");
							let width = img.width;
							let height = img.height;
							if (width === 0 || height === 0) {
								resolve(file);
								return;
							}
							if (width > height) {
								if (width > maxWidth) {
									height = Math.round(height * maxWidth / width);
									width = maxWidth;
								}
							} else if (height > maxHeight) {
								width = Math.round(width * maxHeight / height);
								height = maxHeight;
							}
							canvas.width = width;
							canvas.height = height;
							const ctx = canvas.getContext("2d");
							if (!ctx) {
								resolve(file);
								return;
							}
							ctx.drawImage(img, 0, 0, width, height);
							canvas.toBlob((blob) => {
								try {
									if (!blob) {
										resolve(file);
										return;
									}
									const compressedFile = new File([blob], file.name, {
										type: "image/jpeg",
										lastModified: Date.now()
									});
									console.log(`Original size: ${(file.size / 1024).toFixed(1)}KB, Compressed size: ${(compressedFile.size / 1024).toFixed(1)}KB`);
									resolve(compressedFile);
								} catch (err) {
									console.error("Blob creation error:", err);
									resolve(file);
								}
							}, "image/jpeg", quality);
						} catch (err) {
							console.error("Canvas processing error:", err);
							resolve(file);
						}
					};
					img.onerror = () => {
						clearTimeout(timeoutId);
						resolve(file);
					};
					img.src = event.target.result;
				} catch (err) {
					clearTimeout(timeoutId);
					console.error("Image loading error:", err);
					resolve(file);
				}
			};
			reader.onerror = () => {
				clearTimeout(timeoutId);
				resolve(file);
			};
			reader.readAsDataURL(file);
		} catch (err) {
			clearTimeout(timeoutId);
			console.error("FileReader start error:", err);
			resolve(file);
		}
	});
};
